/*
 * A174850  Quintisection A061037(5*n-2).
 * https://oeis.org/A174850
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy, frac
 * Formula:   A174850 generated by interlaced quadratic polynomials: a(4n) =
 *            5*n*(5*n-1) a(4n+1) = 5*(4*n+1)*(20*n+1) a(4n+2) =
 *            5*(2*n+1)*(10*n+3) a(4n+3) = 5*(4*n+3)*(20*n+11)
 * Range:     u8 n <= 4, u16 n <= 52, u32 n <= 2000, u64 n <= 2000,
 *            u128 n <= 2000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    idx_t r = n % 4;
    switch (r) {
        case 0: {
            idx_t k = n / 4;
            seq_t kk = (seq_t)k;
            return 5 * kk * (5 * kk - 1);
        }
        case 1: {
            idx_t k = (n - 1) / 4;
            seq_t kk = (seq_t)k;
            return 5 * (4 * kk + 1) * (20 * kk + 1);
        }
        case 2: {
            idx_t k = (n - 2) / 4;
            seq_t kk = (seq_t)k;
            return 5 * (2 * kk + 1) * (10 * kk + 3);
        }
        case 3: {
            idx_t k = (n - 3) / 4;
            seq_t kk = (seq_t)k;
            return 5 * (4 * kk + 3) * (20 * kk + 11);
        }
    }
    return 0; /* unreachable */
}
